CREATE TEMPORARY VIEW be_log_data_raw_${grass_region_without_quote} AS
SELECT
    CASE WHEN ads_id > 0 THEN TRUE ELSE FALSE END AS is_ads
    ,CASE WHEN ctx_item_type = 2 THEN TRUE ELSE FALSE END AS is_vitem
    ,FROM_JSON(ad_info, 'STRUCT<cpc_bid:INT,ecpm_weight:DOUBLE,ecpm:DOUBLE>') AS ad_info
    ,ctr_score
    ,cvr_score
    ,rel_lx_score
    ,FROM_JSON(ads_mix_params, 'STRUCT<gmv_boost:DOUBLE,mergescore_boost:DOUBLE,ad_load_boost:DOUBLE
        ,ads_boost:DOUBLE,order_boost:DOUBLE,rel_boost:DOUBLE,tc_boost:DOUBLE>') AS ads_mix_params
FROM
    srdi_mart.dwd_sr_data_warehouse_search_be_log
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW be_log_data_grouped_${grass_region_without_quote} AS
SELECT
    CASE
        WHEN is_ads = TRUE AND is_vitem = TRUE THEN 'ads_vitem'
        WHEN is_ads = TRUE AND is_vitem = FALSE THEN 'ads_not_vitem'
        WHEN is_ads = FALSE AND is_vitem = TRUE THEN 'organic_vitem'
        WHEN is_ads = FALSE AND is_vitem = FALSE THEN 'organic_not_vitem'
    END AS request_type
    ,COUNT(1) AS item_count
    ,SUM(ad_info.cpc_bid) AS cpc_bid
    ,SUM(ad_info.ecpm) AS ecpm
    ,SUM(ad_info.ecpm_weight) AS ecpm_weight
    ,SUM(ctr_score) AS ctr
    ,SUM(cvr_score) AS cvr
    ,SUM(ctr_score * cvr_score) AS ctcvr
    ,SUM(rel_lx_score) AS rel_score
    ,SUM(ads_mix_params.gmv_boost) AS gmv_boost
    ,SUM(ads_mix_params.mergescore_boost) AS mergescore_boost
    ,SUM(ads_mix_params.ad_load_boost) AS ad_load_boost
    ,SUM(ads_mix_params.ads_boost) AS ads_boost
    ,SUM(ads_mix_params.order_boost) AS order_boost
    ,SUM(ads_mix_params.rel_boost) AS rel_boost
    ,SUM(ads_mix_params.tc_boost) AS tc_boost
FROM
    be_log_data_raw_${grass_region_without_quote}
GROUP BY
    1;

--sql_divide_splitter--

INSERT OVERWRITE ${schema}.ads_sr_data_warehouse_search_be_scores_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
