    request_type
    ,item_count
    ,cpc_bid
    ,ecpm
    ,ecpm_weight
    ,ctr
    ,cvr
    ,ctcvr
    ,rel_score
    ,gmv_boost
    ,mergescore_boost
    ,ad_load_boost
    ,ads_boost
    ,order_boost
    ,rel_boost
    ,tc_boost
FROM
    be_log_data_grouped_${grass_region_without_quote};
